    return ADCS_E_RANGE;
}

if (!sm_bdot_state.initialized) {
    status = adcs_bdot_update(&sm_bdot_state, field, time_s, 1.0, &field_rate);
    if (status != ADCS_OK) {
        sm_rejects++;
        return status;
    }
    command->command = (adcs_vec3_t){0, 0, 0};
    command->saturated_axes = 0U;
    torque->x = 0.0;
    torque->y = 0.0;
    torque->z = 0.0;
    return ADCS_OK;
}

if (!(time_s > sm_bdot_state.previous_time_s)) {
    sm_rejects++;
    return ADCS_E_RANGE;
}

status = adcs_bdot_update(&sm_bdot_state, field, time_s, 1.0, &field_rate);
if (status != ADCS_OK) {
    sm_rejects++;
    return status;
}

status = adcs_bdot_dipole(field, &field_rate, gain, limit, &cmd);
if (status != ADCS_OK) {
    sm_rejects++;
    return status;
}
*command = cmd;

*torque = adcs_vec3_cross(&command->command, field);

sm_rejects = 0U;
return ADCS_OK;
